<a class="back-link" href="<?= e(url('rooms')) ?>"><?= icon('chevron-left') ?>Voltar para Salas</a><div class="room-detail-grid"><div><img class="detail-photo" src="public/assets/images/<?= e($record['image']) ?>" alt="<?= e($record['name']) ?>"><section class="card card-body section-gap"><div class="row-title"><span class="inline-meta"><?= icon(room_icon($record['type'])) ?><?= e($record['type']) ?></span><?= badge($record['status']) ?></div><h2><?= e($record['name']) ?></h2><p class="inline-meta spaced"><?= icon('users') ?><?= (int)$record['capacity'] ?> pessoas <span class="meta-spacer"></span><?= icon('map-pin') ?><?= e($record['floor']) ?></p><p class="description"><?= e($record['description']) ?></p><h4 class="eyebrow">Recursos</h4><div class="feature-list"><?php foreach(explode(',',$record['features']) as $feature): ?><span><?= icon('check') ?><?= e(trim($feature)) ?></span><?php endforeach; ?></div></section></div><section class="card card-body availability"><h3>Disponibilidade</h3><form method="get" class="date-filter"><input type="hidden" name="page" value="rooms"><input type="hidden" name="action" value="show"><input type="hidden" name="id" value="<?= (int)$record['id'] ?>"><label for="availability-date">Data</label><input type="date" id="availability-date" name="date" value="<?= e($date) ?>" data-autosubmit><noscript><button class="button">Consultar</button></noscript></form><p class="label-small">Horários</p><div class="time-slots"><?php for($hour=7;$hour<18;$hour++): $time=sprintf('%02d:00',$hour);$busy=null;foreach($bookings as $b){if(in_array($b['status'],['Pendente','Confirmado'],true)&&substr($b['start_time'],0,5)<=$time&&substr($b['end_time'],0,5)>$time){$busy=$b;break;}} ?><div class="time-slot <?= $busy?'busy':'' ?>"><span><?= $time ?></span><span><?= $record['status']==='Manutenção'?'Manutenção':($busy?e($busy['teacher']):'Livre') ?></span></div><?php endfor; ?></div><?php if($record['status']!=='Manutenção'): ?><a class="button full" href="<?= e(url('booking',['action'=>'create','room'=>$record['id'],'date'=>$date])) ?>"><?= icon('plus') ?>Reservar esta sala</a><?php else: ?><p class="alert">Reservas indisponíveis durante a manutenção.</p><?php endif; ?></section></div>

